={{ (() => {
  const d = $('브리핑 데이터').item.json;
  const c = $json && $json.choices && $json.choices[0] && $json.choices[0].message ? $json.choices[0].message.content : '';
  const llm = (typeof c === 'string' ? c : '').trim();
  const L = [];
  L.push('☀️ *아침 브리핑* — ' + d.today + ' (' + d.weekday + ')');
  L.push('');
  L.push('📚 어학 복습 대기 *' + d.due_reviews + '건*  (활성 항목 ' + d.active_items + ')');
  L.push('🔎 신규 리드 *' + d.new_leads + '건*  · 미처리 ' + d.open_leads + '건');
  L.push('🧩 활성 파트 ' + d.active_parts + '개');
  if (llm) { L.push(''); L.push('💡 _' + llm.replace(/\n+/g, ' ') + '_'); }
  L.push('');
  L.push('_일정(Google Calendar)은 OAuth 연결 후 이 브리핑에 추가됩니다._');
  return L.join('\n');
})() }}
